	@Test
	void plannedMemoizedOptionalEvictsLeastRecentlyUsedCorrelationKey() {
		String property = LeftJoinQueryEvaluationStep.MAX_MEMOIZED_KEYS_PROPERTY;
		String previousValue = System.setProperty(property, "1");
		try {
			Value firstRoot = VALUE_FACTORY.createIRI("urn:root:first");
			Value secondRoot = VALUE_FACTORY.createIRI("urn:root:second");
			StatementPattern leftArg = statementPattern("root", "leftValue");
			StatementPattern rightArg = statementPattern("root", "detail");
			LeftJoin leftJoin = new LeftJoin(leftArg, rightArg);
			leftJoin.setStringMetricPlanned("optimizer.leftJoinAlgorithmHint", "memoized");
			List<BindingSet> leftRows = List.of(
					row("root", firstRoot), row("root", secondRoot), row("root", firstRoot));
			AtomicInteger rightEvaluations = new AtomicInteger();
			QueryEvaluationStep left = ignored -> new CloseableIteratorIteration<>(leftRows.iterator());
			QueryEvaluationStep right = bindings -> {
				rightEvaluations.incrementAndGet();
				QueryBindingSet result = new QueryBindingSet(bindings);
				result.addBinding("detail", VALUE_FACTORY.createLiteral(bindings.getValue("root").stringValue()));
				return new CloseableIteratorIteration<>(List.<BindingSet>of(result).iterator());
			};
			QueryEvaluationStep step = plannedOptionalStep(leftArg, rightArg, leftJoin, left, right);

			List<BindingSet> results = new ArrayList<>();
			try (var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
				while (iteration.hasNext()) {
					results.add(iteration.next());
				}
			}

			assertEquals(List.of(firstRoot, secondRoot, firstRoot),
					results.stream().map(row -> row.getValue("root")).toList());
			assertEquals(3, rightEvaluations.get());
		} finally {
			if (previousValue == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previousValue);
			}
		}
	}

