	private static StatementPattern statementPattern(String subjectName, String objectName) {
		return new StatementPattern(
				new Var(subjectName),
				new Var("predicate", VALUE_FACTORY.createIRI("urn:predicate:" + objectName)),
				new Var(objectName));
	}

	private static QueryEvaluationStep plannedOptionalStep(StatementPattern leftArg, StatementPattern rightArg,
			LeftJoin leftJoin, QueryEvaluationStep left, QueryEvaluationStep right) {
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		doReturn(left).when(strategy).precompile(eq((TupleExpr) leftArg), eq(context));
		doReturn(right).when(strategy).precompile(eq((TupleExpr) rightArg), eq(context));
		return LeftJoinQueryEvaluationStep.supply(strategy, leftJoin, context);
	}

	private static BindingSet row(String bindingName, Value value) {
		QueryBindingSet row = new QueryBindingSet(1);
		row.addBinding(bindingName, value);
		return row;
	}
